quests[10471] = { id = 10471, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defender's Oath", description = "You've carried out the promise you made to us, {name}.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", sourceObjective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands.", progress = "You've returned.  You wish to speak to me?", completion = "You are a worthy ally indeed.  As you grow in power so does the band of eternity!", sourceObjectiveStatus = "unverified-source-field" }
quests[10472] = { id = 10472, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sage's Covenant", description = "Your accomplishments have gone beyond my greatest expectations, {name}.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", sourceObjective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.", progress = "May time always be on your side, {name}.", completion = "You are one with time, {name}.  You are one with us.\n\nBehold!  Power beyond mortal understanding is unleashed from even that small remnant of the Well of Eternity.\n\nAccept this gift so that all may know of your covenant with the Scale of the Sands.... so that all may know of your covenant with time itself!", sourceObjectiveStatus = "unverified-source-field" }
quests[10473] = { id = 10473, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restorer's Covenant", description = "Your accomplishments have gone beyond my greatest expectations, {name}.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", sourceObjective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.", progress = "May time always be on your side, {name}.", completion = "You are one with time, {name}.  You are one with us.\n\nBehold!  Power beyond mortal understanding is unleashed from even that small remnant of the Well of Eternity.\n\nAccept this gift so that all may know of your covenant with the Scale of the Sands.... so that all may know of your covenant with time itself!", sourceObjectiveStatus = "unverified-source-field" }
quests[10474] = { id = 10474, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion's Covenant", description = "Your accomplishments have gone beyond my greatest expectations, {name}.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", sourceObjective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.", progress = "May time always be on your side, {name}.", completion = "You are one with time, {name}.  You are one with us.\n\nBehold!  Power beyond mortal understanding is unleashed from even that small remnant of the Well of Eternity.\n\nAccept this gift so that all may know of your covenant with the Scale of the Sands.... so that all may know of your covenant with time itself!", sourceObjectiveStatus = "unverified-source-field" }
quests[10475] = { id = 10475, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defender's Covenant", description = "Your accomplishments have gone beyond my greatest expectations, {name}.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", sourceObjective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.", progress = "May time always be on your side, {name}.", completion = "You are one with time, {name}.  You are one with us.\n\nBehold!  Power beyond mortal understanding is unleashed from even that small remnant of the Well of Eternity.\n\nAccept this gift so that all may know of your covenant with the Scale of the Sands.... so that all may know of your covenant with time itself!", sourceObjectiveStatus = "unverified-source-field" }
quests[10476] = { id = 10476, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fierce Enemies", description = "If you seek to prove your loyalty to us, there is no better way than to fight against our enemies.\n\nOf these, there are none that can match the ogres in strength and fierceness.  Bring me the warbeads they wear around their necks as proof of their demise and I'll let the others know of your prowess.", sourceObjective = "Warden Moi'bff Jill at Telaar wants you to obtain 10 Obsidian Warbeads from the various ogres that inhabit Nagrand.", progress = "Well, {name}?  Are you all talk or do you have something to show me?", completion = "You're starting to prove your worth as an ally and combatant.  Keep up the good work.", sourceObjectiveStatus = "unverified-source-field" }
quests[10477] = { id = 10477, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Warbeads", progress = "Do you bear any additional obsidian warbeads, {name}?", completion = "You continue to prove your worth to us, {name}.  May your strength never fail you." }
quests[10478] = { id = 10478, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Warbeads!", progress = "Have you obtained more warbeads, {name}?", completion = "You continue to prove your strength and honor, {name}." }
quests[10479] = { id = 10479, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Your Strength", description = "Though we seek a peaceful life, our enemies are many.  Of these, none match the ogres in sheer brute power.\n\nIf you seek to prove your prowess to us, bring me the warbeads they wear around their necks.  I will tell others of your accomplishments.", sourceObjective = "Warden Bullrok at Garadar wants you to obtain 10 Obsidian Warbeads from the various ogres that inhabit Nagrand.", progress = "You have something to show me, {name}?", completion = "You are a strong ally indeed, {name}.  Going head to head against the ogres of Outland is not something that just anyone can do.", sourceObjectiveStatus = "unverified-source-field" }
quests[10480] = { id = 10480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enraged Spirits of Water", description = "The Illidari naga of the region have taken control of the only clean water supply that exists in Shadowmoon Valley.\n\nDirectly north of here you will find the lair of the naga: Coilskar. Around Coilskar are pockets of agitated water that howl to the land in anguish. It is at those pockets that the enraged spirits of water now wander.\n\nTravel to Coilskar and use the totem of spirits to capture watery souls. You will find the largest concentration of these spirits near Coilskar Cistern.", sourceObjective = "Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley wants you to use the Totem of Spirits to capture 5 Watery Souls.", progress = "Wherever you find naga you will almost certainly find tortured water spirits.", completion = "Only air remains, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10481] = { id = 10481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enraged Spirits of Air", description = "Venture southeast, hero. When you see fields of gigantic blue crystals jutting out from the land, you will have reached your destination. It is there, at the Netherwing Fields, that you will find the enraged spirits of air. They roam the cliffs and mountain bases that surround the fields.\n\nDestroy their tortured forms and capture their souls with the totem of spirits. Return to me when this is done.", sourceObjective = "Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley wants you to use the Totem of Spirits to capture 10 Airy Souls.", progress = "Soon, we will speak with the spirits.", completion = "Allow me to reward you for undertaking such an arduous task, hero.\n\nNow, we must get to work! Please stand back so that I may place the totem and unleash the souls.", sourceObjectiveStatus = "unverified-source-field" }
quests[10482] = { id = 10482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Orc Scavengers", description = "Scavengers, orcs of the Bonechewer clan, skulk about the ruined battlements overlooking the Path of Glory.  We must assume that these fel orcs are gathering war machine parts for their masters within Hellfire Citadel -- they must be stopped!\n\nFind Bonechewer orcs to the north, {name}.  Find them and slay them!  But use caution, for although these orcs are the lesser of the fel orc clans, their strength is the match of any green-skinned orc we've faced thus far...", sourceObjective = "Kill 20 Bonechewer Orcs and return to Amadi in Honor Hold.", progress = "The Bonechewers appear in large numbers, {name}.  Slay them or the fel orcs may overrun us!", completion = "Very good.  I'm sure their loss will be felt in Hellfire Citadel.  Although that dark bastion looms over us and seems nigh insurmountable, it is only with bold moves like you have made that we will find victory over the fel orcs!", sourceObjectiveStatus = "unverified-source-field" }
quests[10483] = { id = 10483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ill Omens", description = "{name}, in our battles with the Bleeding Hollow clan of fel orcs, we have found upon them foreboding trinkets.  These orcs have collected the insignias of fallen Honor Hold soldiers and created cursed talismans from them.  We fear the dark magic of the Bleeding Hollow orcs have transformed our insignias into evil charms with powers against us!\n\nFind such a talisman from the Bleeding Hollow orcs of Zeth'Gor, to the east, and bring it to Corporal Ironridge at Expedition Point, northeast of Zeth'Gor.", sourceObjective = "Lieutenant Amadi in Honor Hold wants you to bring 1 Cursed Talisman to Corporal Ironridge at Expedition Point.", progress = "Reporting from Honor Hold, {name}?  That's good -- our campaign against the demons and the fel orcs is running thin on able bodies!", completion = "Ah, you recovered an insignia from the Bleeding Hollow orcs?  Good -- it is outrageous that they use our own symbols against us, and mock our comrades who've fallen to those red-skinned beasts!", sourceObjectiveStatus = "unverified-source-field" }
quests[10484] = { id = 10484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cursed Talismans", description = "{name}, we cannot allow the Bleeding Hollow orcs to possess their cursed talismans!  You must acquire them for us so they may be disposed of, and so the soldiers who owned them may be honored for their sacrifices.\n\nGo to Zeth'Gor, the cursed abode of the Bleeding Hollow, and perform your grim task... return to me when you have collected the talismans.", sourceObjective = "Bring 12 Cursed Talismans to Corporal Ironridge at Expedition Point.", progress = "Do you have the talismans, {name}?  It pains me to know that those cursed orcs possess our soldiers insignias...", completion = "Thank you, {name}.  My heart is saddened to see these talismans -- they underline the great losses we of Honor Hold have suffered against the fel orcs.  But I am heartened to see you successful against them.  If we can kill enough, perhaps we might emerge from this war victorious.", sourceObjectiveStatus = "unverified-source-field" }
quests[10485] = { id = 10485, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warlord of the Bleeding Hollow", description = "You have shown great strength and fortune, for you have delved into Zeth'Gor and lived!  Now, let us hope your fortune holds, for I have a dire task to ask of you...\n\nWarlord Morkh sits within the barracks of Zeth'Gor, commanding his fel troops against us.  His tactics are as clever as they are cruel, and I must admit that his successes against us have cut deep.  And so, {name}, I ask you to remove Morkh from his seat.  Bring me his armor so that we might display it for our soldiers and bolster them.", sourceObjective = "Bring Warlord Morkh's Shattered Armor to Corporal Ironridge in Expedition Point.", progress = "Do you have Morkh's shattered armor?  Have you braved Zeth'Gor again?", completion = "You've done it!  Morkh is slain!  Now, we have a fighting chance against the fel orc beasts!\n\nThank you, {name}.  Your aid to the war effort here is beyond measure.", sourceObjectiveStatus = "unverified-source-field" }
quests[10486] = { id = 10486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Encroaching Wilderness", description = "The Thunderlord were once a proud orc clan before they were transformed into fel orcs through the blood of Mannoroth.\n\nRecently we recovered this orc stronghold from the ogres that infest the ravine below.  They had moved in when the Thunderlord clan abandoned it.\n\nWe will keep this place and I will have your help doing so.\n\nIn the Jagged Ridge to the south and the west, there are bloodletters that have become like a plague upon us.  They eat and breed incessantly.\n\nKill them and then return to me.", sourceObjective = "Gor'drek has asked you to slay 12 Bladewing Bloodletters. Return to him at Thunderlord Stronghold in the Blade's Edge Mountains once you have accomplished that.", completion = "That didn't take as long as I thought it would.  Are you sure that you dealt with as many as was necessary?\n\nVery well, there's something else that I want you to help us with.  Something far more important.", sourceObjectiveStatus = "unverified-source-field" }
quests[10487] = { id = 10487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dust from the Drakes", description = "The Alliance has recently moved in to the west, using their elven magics to grow a town and grove in a short matter of time.  We must keep their defenses weak so that they do not also grow a spine.\n\nI have a plan that will do that and more.  I want you to traverse the bridge to the southwest, which crosses over Bloodmaul Ravine and leads into the Living Grove.\n\nAttack their fey drake defenses in the Living Grove and bring back the magical dust that sometimes can be found upon their wings.", sourceObjective = "Gor'drek wants you to gather 4 Dusts of the Fey Drake. After doing so, return to him at Thunderlord Stronghold in the Blade's Edge Mountains.", progress = "It would seem that the Alliance is determined to follow us wherever we go.  Let us teach them that we are not intimidated by their presence.\n\nDo you have that which I have requested?", completion = "Not only have you weakened their defenses, but we're going to put this dust to use in bolstering our own defenses against the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[10488] = { id = 10488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Protecting Our Own", description = "With the magical dust you recovered, I have fashioned a magic ointment that will aid in our own defenses.\n\nOur dire wolves are the perfect combination of mount, sentry and friend, but the Alliance scum have been poaching them in the Jagged Ridge.\n\n{name}, I want you to take this ointment and apply it to our dire wolf friends.  The Alliance will get a rude surprise the next time that they send one of their hunting parties.\n\nBe aware though that some of the wolves may not like this, and will turn on you.", sourceObjective = "Use Gor'drek's Ointment on 5 of the Thunderlord Dire Wolves to strengthen them and the defense of the Jagged Ridge. Then return to Gor'drek at Thunderlord Stronghold in the Blade's Edge Mountains.", progress = "How fares the bolstering of our Thunderlord dire wolves' defenses?", completion = "Now that you have strengthened the wolves, and the Jagged Ridge's defenses, perhaps we can refocus our attentions on more deadly matters, such as the ogres?\n\nYou have done a good job in aiding us here.  We could use the help of someone capable, such as yourself, should you decide to stay.\n\nWhatever you do, you have earned my respect and appreciation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10489] = { id = 10489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Felling an Ancient Tree", description = "WANTED!\n\nStronglimb Deeproot, ancient of war and chief defender of the Living Grove south of Sylvanaar.\n\nFind him by heading west across the bridge that traverses the Bloodmaul Ravine.\n\nReturn his hewn trunk to Tor'chunk Twoclaws inside the Thunderlord Stronghold inn.", sourceObjective = "Acquire Stronglimb Deeproot's Trunk and deliver it to Tor'chunk Twoclaws at Thunderlord Stronghold in the Blade's Edge Mountains.", progress = "What's that you have there?  You're a strong one!", completion = "Stronglimb Deeproot's Trunk!  Did you chop him down by yourself?\n\nI bet you did.  You know, Rexxar and I are looking for a young, strong {class}, such as yourself, to help out around here, especially with the problems we continually have with the ogres.  Make sure that you follow-up with me on that possibility.\n\nWell that trunk's definitely proof, which means you're here to collect the bounty and not to listen to me talk.  Go ahead, take your pick.", sourceObjectiveStatus = "unverified-source-field" }
quests[10490] = { id = 10490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Water", description = "I'm sensing that it's been a while since last you were tested.  This is because Farseer Nobundo has been asking for you.\n\nYou must have grown greatly in wisdom because you are being called to learn the mysteries of the element of water.\n\nI trust that you remember how to take the boat from Auberdine in Darkshore on Kalimdor back to the Exodar?  And that you remember where to find the farseer at the Crystal Hall inside the Exodar, yes?", sourceObjective = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.", completion = "We meet again.  I have been watching your progress from afar, {class}, and I am pleased.\n\nThe time has come for you to commune with the element of water, to learn its mysteries and give yourself over to the water so that you might in turn learn to master it.", sourceObjectiveStatus = "unverified-source-field" }
quests[10491] = { id = 10491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of Air", description = "{name}, once again Farseer Nobundo has been asking for you.  It must be time for you to learn the secrets of air, the last of the elements!\n\nI want you to know that I'm very proud of all that you have accomplished thus far.  I know that you have great things ahead of you.\n\nTake the boat from Auberdine in Darkshore on Kalimdor.  Cross the Veiled Sea and seek out the farseer inside the Crystal Hall of the Exodar on Azuremyst Isle.", sourceObjective = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.", completion = "And finally we come to it, the last of the four great elements: air.  Do you think yourself wise enough to continue, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[10492] = { id = 10492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earnest Proposition", description = "Well met, {class}.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", sourceObjective = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Bindings of Elements to Deliana in Ironforge.", progress = "Have you brought me what I requested of you, {name}?", completion = "Excellent!  Let's perform the trade then.  It's hard to part with this excellent armor, but I'm afraid I won't be needing it any time soon.\n\nIf you're interested in performing more work for me, I might be willing to give up the rest of the pieces.", sourceObjectiveStatus = "unverified-source-field" }
quests[10493] = { id = 10493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Earnest Proposition", description = "Hail, {class}!  I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.\n\nPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.\n\nI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange.", sourceObjective = "Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Lightforge Bracers to Mokvar in Orgrimmar.", progress = "Have you obtained the items I require, {name}?", completion = "Ah, yes.  Mux will be quite happy with this.\n\nThose bracers were part of a larger armor set.  If you're interested in providing me with further assistance,  I'd be willing to consider parting with the rest of it.", sourceObjectiveStatus = "unverified-source-field" }
quests[10494] = { id = 10494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Compensation", description = "You kept your word and brought the device built by Mux.  I believe a reward is in order if I'm to keep you interested in saving my skin.  Bring me the belt and set of gloves that you wish to upgrade.  I promise the ones I give you in return will be far superior.", sourceObjective = "Bring a Cord of Elements and a set of Gauntlets of Elements to Deliana in Ironforge.", progress = "You're ready to perform the trade?", completion = "You've kept your end of the bargain, I shall keep mine.\n\nJust remember that I'm holding on to the best pieces until your work is finished.", sourceObjectiveStatus = "unverified-source-field" }
quests[10495] = { id = 10495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just Compensation", description = "You've proven to be a very reliable individual, {name}.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.\n\nFor now I will exchange your belt and gloves.  If we both see this through I shall make the rest of the pieces available to you.", sourceObjective = "Bring a Lightforge Belt and a set of Lightforge Gauntlets to Mokvar in Orgrimmar.", progress = "You're ready to perform the exchange?", completion = "Our agreement remains in place.  Just remember, this is but a taste of what awaits you.  Free me of this cursed fate and I will reward you with items of truly great power.", sourceObjectiveStatus = "unverified-source-field" }
quests[10496] = { id = 10496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", sourceObjective = "Return to Deliana in Ironforge with a set of Boots of Elements, a Kilt of Elements and Pauldrons of Elements.", sourceObjectiveStatus = "unverified-source-field" }
quests[10497] = { id = 10497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthion's Parting Words", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the amulet back together.  Return to Mokvar and tell him that Bodley is his only hope for finding the remaining pieces.  Speak to him about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", sourceObjective = "Return to Mokvar in Orgimmar with a set of Lightforge Boots, Lightforge Legplates and Lightforge Spaulders.", sourceObjectiveStatus = "unverified-source-field" }
quests[10498] = { id = 10498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Best for Last", description = "That's an amazing story, {name}! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.\n\nAs to your reward, I believe I have a few things that you'll really enjoy.", sourceObjective = "Give Deliana your Coif of Elements and Vest of Elements.", sourceObjectiveStatus = "unverified-source-field" }
quests[10499] = { id = 10499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving the Best for Last", description = "A truly amazing story, {name}! You have my thanks, and the heartfelt gratitude of all who were involved, I can assure you. Through your efforts we are delivered from the mistakes of our past.\n\nAs to your reward, I believe I have a few things that you have definitely earned and will truly enjoy.", sourceObjective = "Give Mokvar your Lightforge Helm and Lightforge Breastplate.", sourceObjectiveStatus = "unverified-source-field" }
quests[10500] = { id = 10500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Horde Needs Your Help!", description = "Hello, I'm glad that you've decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, {name}!\n\nYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, {class}? Will you help out with the vital preparations?", sourceObjective = "Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.", sourceObjectiveStatus = "unverified-source-field" }
quests[10501] = { id = 10501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alliance Needs Your Help!", description = "Hello, I'm glad that you've decided to hear me out. The Alliance needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, {name}!\n\nYou should go speak with the guy in charge, Field Marshal Snowfall. What do you say, {class}? Will you help out with the vital preparations?", sourceObjective = "Speak with Field Marshal Snowfall in Ironforge's Military Ward.", sourceObjectiveStatus = "unverified-source-field" }
quests[10502] = { id = 10502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodmaul Ogres", description = "There is a threat to Sylvanaar far deadlier than the Horde at Thunderlord Stronghold.\n\nI'm speaking of the native ogres of these mountains.  Just to the south and east, down in the ravine, lives the Bloodmaul clan.  While they aren't the only group of ogres that threaten us here, they are the closest.\n\nI would have you head south through the Living Grove, and then go down the path to the east, which leads to their outpost.  Slay as many of the Bloodmaul ogres at Bloodmaul Outpost as you can.", sourceObjective = "Commander Skyshadow has tasked you with the destruction of any 30 Bloodmaul Ogres at Bloodmaul Outpost. Return to him at Sylvanaar in the Blade's Edge Mountains once your gruesome task is completed.", progress = "Our scouts have reported that the Bloodmaul ogres have begun to creep up the switchback, which leads up to the Living Grove from their hold.\n\nIt is unfortunate that we cannot find a way to live together in peace with the ogres, but then, when have we ever been able to do so?", completion = "This is a good first step toward securing Sylvanaar and the grove.\n\nWith their ogres not so numerous, the Bloodmaul will think twice about attacking us here.\n\nNow, if only they were the only clan of ogres that we have to worry about.", sourceObjectiveStatus = "unverified-source-field" }
quests[10503] = { id = 10503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bladespire Threat", description = "There is a threat to Thunderlord Stronghold worse than the Alliance at Sylvanaar.\n\nI speak of the ogres of these mountains.  Just to the west, down in the ravine, lies the Bladespire clan.  While they aren't the only ogres, they are the closest and they're the ones that we defeated to take this place.\n\nHead north through the Jagged Ridge, and then down the path, which leads to their hold.  Slay as many of the Bladespire ogres and their raptors as you can at Bladespire Hold and the Bladespire Grounds.", sourceObjective = "Tor'chunk Twoclaws has tasked you with the destruction of any 30 Bladespire Ogres and 10 Bladespire Raptors at Bladespire Hold and the Bladespire Grounds. Return to him at Thunderlord Stronghold in the Blade's Edge Mountains once your task is completed.", completion = "This is a good first step toward securing our position here against the ogres.\n\nWith their numbers decimated, the Bladespire will think twice about attempting to retake Thunderlord Stronghold.\n\nNow, if they were the only clan of ogres that we have to worry about.", sourceObjectiveStatus = "unverified-source-field" }
quests[10504] = { id = 10504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bladespire Ogres", description = "To the north of the Bloodmaul clan lies a threat more grave:  Bladespire Hold.\n\nThe Bladespire ogres are the strongest clan in the mountains, having the favor of the gronn known as Gruul the Dragonkiller, and his seven sons.\n\nNow that we've dealt with winnowing the Bloodmaul, it is time to turn our eye upon their rivals.\n\nFrom Bloodmaul Hold head north through the ravine until you come to Bladespire Hold and the Bladespire Grounds.  Slay as many of the Bladespire ogres therein as you can.", sourceObjective = "You have been asked by Commander Skyshadow to kill any 30 Bladespire Ogres in Bladespire Hold and the Bladespire Grounds. Return to him at Sylvanaar in the Blade's Edge Mountains once you have done so.", completion = "Your actions against both the Bloodmaul and the Bladespire ogre clans have gone a long way to securing Sylvanaar's future.  While we do not seek to expand past this patch of land, which we initially found empty, we will also not suffer those that would destroy us.\n\nAs you have done us good service, I would reward that service with the appreciation of the Alliance.", sourceObjectiveStatus = "unverified-source-field" }
quests[10505] = { id = 10505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodmaul Ogres", description = "To the south of the Bladespire clan lies yet another threat:  Bloodmaul Outpost.\n\nWhile the Bloodmaul ogres are not the strongest clan in the mountains, not having the favor of the gronn known as Gruul the Dragonkiller, they run a close second.\n\nNow that we've dealt with winnowing the Bladespire, it is time to turn our eye upon their rivals.\n\nFrom Bladespire Hold head south through the ravine until you come to Bloodmaul Outpost.  Slay as many of the Bloodmaul ogres in the vicinity as you can.", sourceObjective = "You have been asked by Tor'chunk Twoclaws to kill any 30 Bloodmaul Ogres at Bloodmaul Outpost. Return to him at Thunderlord Stronghold in the Blade's Edge Mountains once you have done so.", completion = "Your actions against both the Bladespire and the Bloodmaul ogre clans have gone a long way to securing Thunderlord Stronghold's future.  We will not suffer those that would get in the way of our destiny here.\n\nAs you have done good work in destroying these ogres, I intend to reward you with the appreciation of the Horde.", sourceObjectiveStatus = "unverified-source-field" }
quests[10506] = { id = 10506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Dire Situation", description = "With their wolf pack reduced, the Horde is looking for replacements.  Unfortunately there's another source nearby.\n\nThe Bloodmaul ogres in the ravine below to the east keep a strong pack as their own sentries.  I hated sending you to kill the Thunderlord wolves, so why don't we do something different this time?\n\nI've derived a magic powder from the dust that naturally falls off the wings of our fey drakes.  Sprinkle it on the Bloodmaul dire wolves to make them undesirable to the Horde.", sourceObjective = "Rina Moonspring wants you to take her Diminution Powder and apply it to 5 of the Bloodmaul Dire Wolves, which can be found at Bloodmaul Outpost and in Bloodmaul Ravine. After doing so, return to her at Sylvanaar in the Blade's Edge Mountains.", progress = "Any luck out there?  I know that it's dangerous work to be doing this amongst the Bloodmaul ogres, but if we can avoid the killing of any more animals, I'll be happy.", completion = "I'm glad to hear that it worked.  The fewer the number of Nature's creatures that have to die, the better.\n\nWith all that you've done for us already, I must say that I'm beginning to grow very fond of your company.\n\nTake care, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[10507] = { id = 10507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Turning Point", description = "This is the chance we've been waiting for, {name}.  Not only have we uncovered the evidence we need to show our people who Kael'thas is really working for, but we can prove our strength by defeating his new masters.\n\nMy frail health prevents me from aiding you in person with this endeavor, but I will offer you an object that will allow me to project my powers across the continent.", sourceObjective = "Use Socrethar's Teleportation's Stone at Invasion Point: Overlord, north of Forge Base: Oblivion to transport your party to Socrethar's Landing. Once there, use Voren'thal's Presence to defeat Socrethar.\n\nPerforming quests for the Scryers will cause your Aldor reputation to decrease.", progress = "Is it done, {name}?", completion = "You are an individual of formidable power, {name}.  The Scryers are fortunate to count you as an ally.\n\nAs word of Kael's new allegiance spreads, more people will see things our way.  The fact that we can claim such a decisive victory against Kael'thas' new overlords puts us in a most favorable situation.\n\nI will not forget your deeds.", sourceObjectiveStatus = "unverified-source-field" }
quests[10508] = { id = 10508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Gift for Voren'thal", description = "I don't want to send you to Voren'thal empty-handed.  It's not in my style to be underwhelming.\n\nTo gain access to Socrethar's Seat in the north, we'll need to use his own teleporters - locked by Socrethar's teleportation stone.  The first half of the stone is in the possession of Forgemaster Morug at Forge Base Oblivion.  The second half is held by the demon Silroth at Forge Base: Gehenna.\n\nObtain these and Voren'thal will be impressed beyond words.", sourceObjective = "Spymaster Thalodien at Area 52 wants you to obtain the First Half of Socrethar's Stone from Forgemaster Morug at Forge Base: Oblivion and the Second Half of Socrethar's Stone from Silroth at Forge Base: Gehenna.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", progress = "Have you obtained Socrethar's teleportation stone, {name}?", completion = "You do not cease to amaze me, {name}!  Good thing you're on our side.", sourceObjectiveStatus = "unverified-source-field" }
quests[10509] = { id = 10509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bound for Glory", description = "Now I can properly send you back to Shattrath City.  You've uncovered evidence of Kael'thas making pacts with the Burning Legion and you've got the key to the overlord's back door.\n\nMake sure Voren'thal doesn't topple over with excitement from the news - the old man's getting a bit fragile, if you know what I mean.  You'll find him inside the Seer's Library at the Scryer's Tier.", sourceObjective = "Bring Socrethar's Teleportation Stone to Voren'thal the Seer at the Scryer's Tier in Shattrath City.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", completion = "You have no idea what this will mean for the Scryers, {name}.  You will have to excuse me while I catch my breath and assess the situation.", sourceObjectiveStatus = "unverified-source-field" }
quests[10510] = { id = 10510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage tbc fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceFlavor = "tbc", sourceRevision = "fe999319f2c9c4c3cdd1bc60c8ae711c079b175f", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into the Draenethyst Mine", description = "Well it's good to see someone who's willing to help out around here!\n\nBorgrim and I are part of the Explorers' League, and we're here to learn what we can of these mountains.  We've heard all sorts of tales, and I can't wait to get settled in and started.\n\nOne thing in particular has caught my attention.  The night elves speak of a place down in the ravine to the east known as the Draenethyst Mine.  It's at the south end of Bloodmaul Outpost.  I'd like some of the crystals that grow naturally therein.", sourceObjective = "Bronwyn Stouthammer has asked you to collect 5 Draenethyst Mine Crystals and then return to her at Sylvanaar in the Blade's Edge Mountains.", progress = "Isn't this exciting?  After all of the dirt and insects of Silithus, this place is like a paradise.", completion = "Ooh, by the looks of those, they're fine specimens.  I can't wait to get my examination tools unpacked and have a real look at them!\n\nThank you!", sourceObjectiveStatus = "unverified-source-field" }
